mapper.select:
SELECT CPU_UTILIZATION_RATE AS cpuUtilizationRate,
INSERT_TIME AS insertTime
from MONITOR_DOCKER_STATS_HISTORY
WHERE SERVER_IP = #{params.serverIp}
AND CONTAINER_NAME=#{params.containerName}

    AND INSERT_TIME BETWEEN #{params.startTime} AND #{params.endTime}

